import {
	HexTile,
	HexValidationSettings,
	RemoveBridgingLandmassOptions,
	SeparationFilterOptions,
	VoronoiValidationSettings,
} from "#base/scripts/hex-map.js";
import { PlayerRegion } from "#base/scripts/player-areas.js";
import { RegionType } from "#base/scripts/voronoi-types.js";
import shatteredSeasSettings from "#base/scripts/voronoi_data/shattered-seas.mapconfig.js";
import { MapSettingSchema } from "#base/scripts/voronoi_maps/map-common.js";
import {
	SectionSettings,
	UnifiedContinentsBase,
	UnifiedContinentsBaseSettings,
} from "#base/scripts/voronoi_maps/unified-continents-base.js";

export interface VoronoiShatteredSeasSettings extends UnifiedContinentsBaseSettings {
	landmassFactor: number;
	distantFactor: number;
}

export const shatteredSeasMapSchema = {
	landmassFactor: {
		label: "Landmass Factor",
		description:
			"The number of main landmasses per player according to the standard player count of a specific map size.",
		default: 1,
		min: 0.5,
		max: 4.0,
		step: 0.1,
	},
	distantFactor: {
		label: "Distant Factor",
		description:
			"The number of distant landmasses per player according to the standard player count of a specific map size.",
		default: 0.33,
		min: 0.0,
		max: 1,
		step: 0.01,
	},
} satisfies MapSettingSchema;

export function buildShatteredSeasSettings(source: VoronoiShatteredSeasSettings, hexDims: float2): SectionSettings {
	const result: SectionSettings = { ...source };

	const tileCount = hexDims.x * hexDims.y;
	const landmassFactor = source.landmassFactor;
	const distantFactor = source.distantFactor;
	const playerCountFactor = 570; // maps have about 570 tiles per supported player, we want about 1.5 players per continent

	result.landmassCount = Math.round((tileCount * landmassFactor) / playerCountFactor);
	result.distantCount = Math.round((tileCount * distantFactor) / playerCountFactor);
	result.minDistantSpawnCenterDistance = 0.25;
	result.maxDistantSpawnCenterDistance = 0.5;

	return result;
}

export class VoronoiShatteredSeas extends UnifiedContinentsBase<VoronoiShatteredSeasSettings> {
	constructor() {
		super(shatteredSeasMapSchema, shatteredSeasSettings);
	}

	init(hexDims: float2) {
		this.m_baseSchema.landmassCount.hidden = true;
		this.m_baseSchema.distantCount.hidden = true;

		this.initInternal(hexDims);
	}

	simulateInternal(): void {
		const hexValidationSettings = new HexValidationSettings();
		hexValidationSettings.removeBridgingPlayerLandmasses = RemoveBridgingLandmassOptions.FORCE_COASTS;
		this.getHexTiles().setValidationSettings(hexValidationSettings);

		super.placeDefaultSection(buildShatteredSeasSettings(this.m_settings, this.m_hexDims));
	}

	protected override getVoronoiValidationSettings(): VoronoiValidationSettings {
		const voronoiValidationSettings = new VoronoiValidationSettings();
		voronoiValidationSettings.forceOceans = SeparationFilterOptions.DIFFERENT_LANDMASS_GROUPS;
		voronoiValidationSettings.forceCoasts = SeparationFilterOptions.ALL;
		return voronoiValidationSettings;
	}

	/**
	 * Creates major player areas by assigning players to landmasses in a round-robin fashion.
	 *
	 * Landmasses are sorted by size (largest first) and players are distributed across them.
	 * Player area IDs are adjusted based on landmass offsets, and landmass IDs are normalized
	 * (set to 1 for non-island continents, 0 otherwise).
	 *
	 * @param valueFunction - Optional function to evaluate tile values for area assignment
	 * @remarks
	 * - All landmasses should be close in size for balanced distribution
	 * - The map is treated as a "pangaea" where player regions span across landmasses
	 * - Non-island regions in group 0 have their landmassId set to 1, others to 0
	 */
	createMajorPlayerAreas(valueFunction?: (tile: HexTile) => number): void {
		const regions = this.getGenerator().getLandmasses();
		const landmassIds = regions.reduce<number[]>((out, value, index) => {
			if (value.groupId > 0 && value.type == RegionType.Landmass) out.push(index);
			return out;
		}, []);
		landmassIds.sort((a, b) => regions[b].cellCount - regions[a].cellCount);

		// Round-robin assign players to landmasses starting with the biggest first. All landmasses should be close in size, but
		// if we want more variation then this may need to be adjusted.
		const playerRegions: PlayerRegion[] = new Array(landmassIds.length);
		for (let i = 0; i < playerRegions.length; ++i) {
			playerRegions[i] = new PlayerRegion();
			playerRegions[i].id = landmassIds[i];
			playerRegions[i].filter = (tile: HexTile): boolean => {
				const cell = this.getRegionCellForHex(tile.coord.x, tile.coord.y);
				return cell?.landmassId === landmassIds[i];
			};
		}
		for (let i = 0; i < this.getSettings().totalPlayers; ++i) {
			++playerRegions[i % landmassIds.length].playerAreas;
		}
		super.createMajorPlayerAreas(valueFunction, playerRegions);
	}

	static getName(): string {
		return "Shattered Seas";
	}

	getFilename(): string {
		return "shattered-seas.mapconfig.js";
	}
}
